from typing import TypedDict

class Entry(TypedDict):
    sequence: int
    balance: int

class Ledger(TypedDict):
    rows: list[Entry]

def post(opening: Ledger, amount: int) -> Ledger:
    rows = opening["rows"]
    entry = Entry(sequence=len(rows) + 1, balance=amount - 1)
    return Ledger(rows=[*rows, entry])

